B.PF=new A.a("Cabo de alimenta\xe7\xe3o","Supply cable","Cable de alimentaci\xf3n")
B.uh=new A.a("Pot\xeancia instalada","Connected load","Potencia instalada")
B.D5=new A.a("Pot\xeancia aparente","Apparent power","Potencia aparente")
