B.tT=new A.a("Pot\xeancia m\xe9dia","Average power","Potencia media")
B.aaw=new A.a("Bra\xe7o, VRI e el\xe9trica","Arm, VRI and electrical","Brazo, VRI y el\xe9ctrica")
B.acE=new A.a("Carta de bocais do piv\xf4","Pivot nozzle chart","Carta de boquillas del pivote")
B.a6z=new A.a("Sem piv\xf4s ou lineares calculados: desenhe um piv\xf4 (PV) e calcule o projeto.","No designed pivots or linear moves: draw a pivot (PV) and run the design.","Sin pivotes ni lineales calculados: dibuje un pivote (PV) y calcule el dise\xf1o.")
B.ac0=new A.a("Nenhum bra\xe7o de canto, prescri\xe7\xe3o de taxa vari\xe1vel ou projeto el\xe9trico de piv\xf4: configure-os no pacote do piv\xf4 (propriedades do piv\xf4).","No corner arm, variable-rate prescription or pivot electrical design: set them up in the pivot package (pivot properties).","Ning\xfan brazo de esquina, prescripci\xf3n de tasa variable o dise\xf1o el\xe9ctrico de pivote: config\xfarelos en el paquete del pivote (propiedades del pivote).")
B.CX=new A.a("Mapa de fundo sob o desenho","Base map under the drawing","Mapa de fondo bajo el dibujo")
B.adw=new A.a("Baixado para tudo o que as folhas mostram, na resolu\xe7\xe3o de impress\xe3o e com o cr\xe9dito do provedor (sem internet: o mapa visto na tela).","Downloaded for everything the sheets show, at print resolution and with the provider's credit (offline: the map seen on screen).","Se descarga para todo lo que muestran las hojas, con resoluci\xf3n de impresi\xf3n y el cr\xe9dito del proveedor (sin internet: el mapa visto en pantalla).")
B.EP=new A.a("Shapefile (QGIS, SIG; .zip por camada)","Shapefile (QGIS, GIS; .zip by layer)","Shapefile (QGIS, SIG; .zip por capa)")
B.oV=new A.a("GPX (GPS: marca\xe7\xe3o no campo)","GPX (GPS: staking out in the field)","GPX (GPS: replanteo en campo)")
B.a4v=new A.a("LandXML (topografia: superf\xedcie e tubos)","LandXML (survey: surface and pipes)","LandXML (topograf\xeda: superficie y tuber\xedas)")
B.adm=new A.a("IFC 4 (BIM)","IFC 4 (BIM)","IFC 4 (BIM)")
B.WT=new A.a("EPANET (.inp, rede hidr\xe1ulica)","EPANET (.inp, hydraulic network)","EPANET (.inp, red hidr\xe1ulica)")
B.qZ=new A.a("GeoJSON: {f} fei\xe7\xf5es, {n} entidades ({crs})","GeoJSON: {f} features, {n} entities ({crs})","GeoJSON: {f} entidades geogr\xe1ficas, {n} entidades ({crs})")
B.tZ=new A.a("GPX: {w} pontos, {r} rotas, {t} trilhas, {n} entidades","GPX: {w} waypoints, {r} routes, {t} tracks, {n} entities","GPX: {w} puntos, {r} rutas, {t} tracks, {n} entidades")
B.a4a=new A.a("LandXML: {s} superf\xedcies, {p} pontos, {n} entidades","LandXML: {s} surfaces, {p} points, {n} entities","LandXML: {s} superficies, {p} puntos, {n} entidades")
B.v8=new A.a("Nuvem de pontos: {n} cotas do terreno ({p} pontos lidos, malha de {c} m)","Point cloud: {n} ground spot heights ({p} points read, {c} m grid)","Nube de puntos: {n} cotas del terreno ({p} puntos le\xeddos, malla de {c} m)")
B.Tf=new A.a("DGN: {n} entidades (unidade {u})","DGN: {n} entities (unit {u})","DGN: {n} entidades (unidad {u})")
B.vC=new A.a("EPANET: {j} n\xf3s, {l} trechos, {n} entidades","EPANET: {j} junctions, {l} links, {n} entities","EPANET: {j} nudos, {l} tramos, {n} entidades")
