B.a6J=new A.a("O assistente quer salvar um arquivo:","The assistant wants to save a file:","El asistente quiere guardar un archivo:")
B.zA=new A.a("Detalhes","Details","Detalles")
B.e8=new A.a("Pular","Skip","Omitir")
B.Cb=new A.a("{m} est\xe1 pensando\u2026","{m} is thinking\u2026","{m} est\xe1 pensando\u2026")
B.E5=new A.a("Executando {n}\u2026","Running {n}\u2026","Ejecutando {n}\u2026")
B.zK=new A.a("Aguardando sua aprova\xe7\xe3o\u2026","Waiting for your approval\u2026","Esperando su aprobaci\xf3n\u2026")
